-- =====================================================================
--  Académie BestaSolar — dotation des trois formations
--  « Démarrer avec BestaSolar Pro », « Créer des devis qui signent »,
--  « Gagner de l'argent avec BestaSolar Pro ».
--
--  FICHIER GÉNÉRÉ — ne pas modifier ici. Source : src/data/formationsAcademie.js
--    node scripts/formations-sql.mjs
--
--  À exécuter dans le SQL Editor (Run), en entier, dans les DEUX projets
--  Supabase : la base de recette, puis la base réelle.
--
--  Rejouable sans risque :
--   - n'ajoute que les cours ABSENTS de l'organisation interne ;
--   - ne modifie jamais un cours déjà là (le gérant a pu le retoucher) ;
--   - ne ressuscite pas un cours que le gérant a supprimé (tombstone).
--  Rien n'est touché dans les autres entreprises : elles lisent les cours de
--  l'organisation interne en partage, sans copie.
-- =====================================================================

do $$
declare
  v_internes int;
  v_org      text;
  v_ajoutes  int;
begin
  if to_regclass('public.orgs') is null
     or not exists (select 1 from information_schema.columns
                     where table_schema = 'public' and table_name = 'formations' and column_name = 'org_id') then
    raise exception 'Base en retard : multitenant.sql (le socle) n''est pas passé. Rien n''a été modifié.';
  end if;

  select count(*) into v_internes from public.orgs where kind = 'interne';
  if v_internes <> 1 then
    raise exception '% organisation(s) interne(s) au lieu d''une : voir organisation-interne.sql. Rien n''a été modifié.', v_internes;
  end if;
  select id into v_org from public.orgs where kind = 'interne';

  insert into public.formations (org_id, id, data)
  select v_org, c ->> 'id', c
    from jsonb_array_elements($academie$[
{"id":"academie-demarrer","title":"Démarrer avec BestaSolar Pro","author":"Académie BestaSolar","description":"Créer son compte, comprendre l’écran, enregistrer son premier client et lancer son premier dimensionnement — même sans réseau. Niveau débutant.","cover":"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%201600%20900%22%3E%20%3Cdefs%3E%3ClinearGradient%20id%3D%22g%22%20x1%3D%220%22%20y1%3D%220%22%20x2%3D%221%22%20y2%3D%221%22%3E%3Cstop%20offset%3D%220%22%20stop-color%3D%22%2308215A%22%2F%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%230D3483%22%2F%3E%3C%2FlinearGradient%3E%3C%2Fdefs%3E%20%3Crect%20width%3D%221600%22%20height%3D%22900%22%20fill%3D%22url(%23g)%22%2F%3E%20%3Ccircle%20cx%3D%221480%22%20cy%3D%22120%22%20r%3D%22260%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.05%22%2F%3E%20%3Ccircle%20cx%3D%22120%22%20cy%3D%22860%22%20r%3D%22220%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.05%22%2F%3E%20%3Ctext%20x%3D%22110%22%20y%3D%22400%22%20fill%3D%22%23FFA800%22%20font-family%3D%22Arial%2C%20Helvetica%2C%20sans-serif%22%20font-size%3D%2224%22%20font-weight%3D%22700%22%20letter-spacing%3D%224%22%3EACAD%C3%89MIE%20BESTASOLAR%3C%2Ftext%3E%20%3Ctext%20x%3D%22110%22%20y%3D%22455%22%20fill%3D%22%23ffffff%22%20font-family%3D%22Arial%2C%20Helvetica%2C%20sans-serif%22%20font-size%3D%2258%22%20font-weight%3D%22700%22%3ED%C3%A9marrer%20avec%3C%2Ftext%3E%3Ctext%20x%3D%22110%22%20y%3D%22515%22%20fill%3D%22%23ffffff%22%20font-family%3D%22Arial%2C%20Helvetica%2C%20sans-serif%22%20font-size%3D%2258%22%20font-weight%3D%22700%22%3EBestaSolar%20Pro%3C%2Ftext%3E%20%3Ccircle%20cx%3D%221330%22%20cy%3D%22285%22%20r%3D%2262%22%20fill%3D%22%23FFA800%22%2F%3E%20%3Cline%20x1%3D%221412%22%20y1%3D%22285%22%20x2%3D%221438%22%20y2%3D%22285%22%20stroke%3D%22%23FFA800%22%20stroke-width%3D%2212%22%20stroke-linecap%3D%22round%22%2F%3E%3Cline%20x1%3D%221387.982756057297%22%20y1%3D%22342.9827560572969%22%20x2%3D%221406.367532368147%22%20y2%3D%22361.3675323681471%22%20stroke%3D%22%23FFA800%22%20stroke-width%3D%2212%22%20stroke-linecap%3D%22round%22%2F%3E%3Cline%20x1%3D%221330%22%20y1%3D%22367%22%20x2%3D%221330%22%20y2%3D%22393%22%20stroke%3D%22%23FFA800%22%20stroke-width%3D%2212%22%20stroke-linecap%3D%22round%22%2F%3E%3Cline%20x1%3D%221272.017243942703%22%20y1%3D%22342.9827560572969%22%20x2%3D%221253.632467631853%22%20y2%3D%22361.3675323681471%22%20stroke%3D%22%23FFA800%22%20stroke-width%3D%2212%22%20stroke-linecap%3D%22round%22%2F%3E%3Cline%20x1%3D%221248%22%20y1%3D%22285%22%20x2%3D%221222%22%20y2%3D%22285%22%20stroke%3D%22%23FFA800%22%20stroke-width%3D%2212%22%20stroke-linecap%3D%22round%22%2F%3E%3Cline%20x1%3D%221272.017243942703%22%20y1%3D%22227.01724394270312%22%20x2%3D%221253.632467631853%22%20y2%3D%22208.63246763185288%22%20stroke%3D%22%23FFA800%22%20stroke-width%3D%2212%22%20stroke-linecap%3D%22round%22%2F%3E%3Cline%20x1%3D%221330%22%20y1%3D%22203%22%20x2%3D%221330%22%20y2%3D%22177%22%20stroke%3D%22%23FFA800%22%20stroke-width%3D%2212%22%20stroke-linecap%3D%22round%22%2F%3E%3Cline%20x1%3D%221387.982756057297%22%20y1%3D%22227.0172439427031%22%20x2%3D%221406.367532368147%22%20y2%3D%22208.63246763185285%22%20stroke%3D%22%23FFA800%22%20stroke-width%3D%2212%22%20stroke-linecap%3D%22round%22%2F%3E%20%3Cg%20transform%3D%22translate(1010%20470)%20skewX(-12)%22%3E%20%3Crect%20width%3D%22300%22%20height%3D%22170%22%20rx%3D%2210%22%20fill%3D%22%231F4FBF%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%226%22%2F%3E%20%3Cline%20x1%3D%22100%22%20y1%3D%220%22%20x2%3D%22100%22%20y2%3D%22170%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%224%22%2F%3E%20%3Cline%20x1%3D%22200%22%20y1%3D%220%22%20x2%3D%22200%22%20y2%3D%22170%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%224%22%2F%3E%20%3Cline%20x1%3D%220%22%20y1%3D%2285%22%20x2%3D%22300%22%20y2%3D%2285%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%224%22%2F%3E%20%3C%2Fg%3E%20%3Cline%20x1%3D%221120%22%20y1%3D%22640%22%20x2%3D%221100%22%20y2%3D%22700%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%2210%22%20stroke-linecap%3D%22round%22%2F%3E%20%3Cline%20x1%3D%221240%22%20y1%3D%22640%22%20x2%3D%221260%22%20y2%3D%22700%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%2210%22%20stroke-linecap%3D%22round%22%2F%3E%20%3Cg%20transform%3D%22translate(1335%20395)%22%3E%20%3Crect%20width%3D%22170%22%20height%3D%22300%22%20rx%3D%2226%22%20fill%3D%22%23ffffff%22%2F%3E%20%3Crect%20x%3D%2214%22%20y%3D%2234%22%20width%3D%22142%22%20height%3D%22222%22%20rx%3D%228%22%20fill%3D%22%230D3483%22%2F%3E%20%3Crect%20x%3D%2228%22%20y%3D%2252%22%20width%3D%22114%22%20height%3D%2222%22%20rx%3D%225%22%20fill%3D%22%23FFA800%22%2F%3E%20%3Crect%20x%3D%2228%22%20y%3D%2288%22%20width%3D%22114%22%20height%3D%2214%22%20rx%3D%224%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.7%22%2F%3E%20%3Crect%20x%3D%2228%22%20y%3D%22112%22%20width%3D%2284%22%20height%3D%2214%22%20rx%3D%224%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.5%22%2F%3E%20%3Crect%20x%3D%2228%22%20y%3D%22146%22%20width%3D%2252%22%20height%3D%2252%22%20rx%3D%228%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.22%22%2F%3E%20%3Crect%20x%3D%2290%22%20y%3D%22146%22%20width%3D%2252%22%20height%3D%2252%22%20rx%3D%228%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.22%22%2F%3E%20%3Ccircle%20cx%3D%2285%22%20cy%3D%22276%22%20r%3D%2211%22%20fill%3D%22%230D3483%22%20opacity%3D%22.35%22%2F%3E%20%3C%2Fg%3E%20%3C%2Fsvg%3E","modules":[{"id":"ad-m1","title":"Créer son compte et rejoindre son équipe","lecons":[{"id":"ad-m1-l1","title":"Créer son compte","type":"texte","duration":"4 min","description":"Objectif : créer votre compte BestaSolar Pro et vous connecter.","content":"Sur l’écran de connexion, touchez « Créer un compte ». L’application demande votre nom complet, votre numéro de téléphone, votre e-mail et un mot de passe d’au moins 8 caractères.\n\nLe numéro se tape sans l’indicatif : choisissez d’abord le pays dans la liste à gauche du champ (Bénin, Togo, Côte d’Ivoire…). Au Bénin, le numéro compte 10 chiffres.\n\nDernier champ, « Code partenaire (facultatif) » : le code de la personne qui vous a recommandé l’application, sous la forme NOM-XXXXXX. Arrivé par son lien, il est déjà rempli. Sinon, vous pourrez le saisir une seule fois plus tard, dans Plus → Parrainage.\n\nTouchez « Créer mon compte ». Si un e-mail de confirmation vous est envoyé, ouvrez le lien qu’il contient, puis connectez-vous avec votre e-mail et votre mot de passe.\n\nExemple — Koffi, installateur à Cotonou, choisit le Bénin dans la liste, tape 0197123456, puis le code AWA-K7P2QX que sa collègue lui a envoyé sur WhatsApp. Une minute plus tard, il est dans l’application.\n\nErreurs fréquentes sur le terrain :\n- Taper l’indicatif (+229) dans le numéro alors que le pays est déjà choisi.\n- Créer deux comptes avec deux e-mails différents : vos clients se retrouvent éparpillés.\n- Saisir un code partenaire au hasard : il devient votre parrain pour de bon.","actionTitle":"L’essentiel","actionContent":"- Le pays se choisit dans le champ du téléphone, avant le numéro.\n- Le code partenaire est facultatif, mais il ne s’attribue qu’une fois.\n- Un seul compte par personne, avec un mot de passe de 8 caractères au moins."},{"id":"ad-m1-l2","title":"Gérant ou technicien : qui fait quoi","type":"texte","duration":"3 min","description":"Objectif : savoir ce que votre rôle vous permet de faire dans l’application.","content":"Il y a deux rôles. Le gérant dirige l’entreprise : il voit tous les clients et tous les devis, valide les ventes et règle les commissions. Le technicien travaille sur ses propres clients et ses propres devis.\n\nLe rôle ne se choisit pas à l’inscription : un compte créé seul est un compte technicien. Pour rejoindre une équipe, le plus simple est le lien d’invitation : le gérant ouvre Plus → Équipe, touche « Copier » sous « Inviter un technicien », et vous l’envoie.\n\nEn ouvrant ce lien, vous créez votre compte et arrivez directement dans l’équipe. Le gérant retrouve alors votre profil et vos performances dans Plus → Équipe.\n\nUne règle à connaître : quand un technicien fait passer une affaire à « Gagné », l’application affiche « Le changement d’étape sera soumis à la validation du gérant ». C’est le gérant qui confirme une vente.\n\nExemple — À Lomé, Mme Amouzou, gérante, envoie le lien d’invitation à ses deux techniciens sur WhatsApp. Le soir même, elle voit leurs premiers clients apparaître.\n\nErreurs fréquentes sur le terrain :\n- S’inscrire seul puis attendre d’« apparaître » dans l’équipe : demandez le lien d’invitation au gérant.\n- Croire qu’une affaire passée à « Gagné » par un technicien est déjà une vente : elle attend la validation du gérant.","actionTitle":"L’essentiel","actionContent":"- Gérant : toute l’équipe, la validation des ventes, les commissions.\n- Technicien : ses propres clients et ses propres devis.\n- Pour rejoindre une équipe : le lien « Inviter un technicien » du gérant."},{"id":"ad-m1-quiz","title":"Quiz — Votre compte","type":"quiz","duration":"2 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"ad-m1-quiz-q1","question":"Où choisit-on le pays au moment de l’inscription ?","choix":["Dans la liste à gauche du champ téléphone","Dans un écran « Pays » après l’inscription","On ne peut pas le choisir"],"bonne":0,"explication":"Le pays se choisit dans le champ du numéro de téléphone : il fixe l’indicatif. On tape ensuite le numéro sans l’indicatif."},{"id":"ad-m1-quiz-q2","question":"Vous voulez rejoindre l’équipe de votre gérant. Que faites-vous ?","choix":["Je m’inscris seul et j’attends","Je saisis son nom dans le code partenaire","J’ouvre le lien « Inviter un technicien » qu’il m’a envoyé"],"bonne":2,"explication":"Le lien d’invitation (Plus → Équipe) crée votre compte directement dans son équipe. Le code partenaire, lui, sert au parrainage."},{"id":"ad-m1-quiz-q3","question":"Un technicien passe une affaire à « Gagné ». Que se passe-t-il ?","choix":["La vente est enregistrée tout de suite","Le changement est soumis à la validation du gérant","L’affaire est supprimée"],"bonne":1,"explication":"L’application le dit : « Le changement d’étape sera soumis à la validation du gérant ». C’est lui qui confirme la vente."}]}]},{"id":"ad-m2","title":"Tour de l’interface","lecons":[{"id":"ad-m2-l1","title":"Le tableau de bord","type":"texte","duration":"4 min","description":"Objectif : lire en un coup d’œil où en est votre activité.","content":"Le tableau de bord vous accueille par « Bonjour » et votre prénom. Juste dessous, une rangée de pastilles résume votre activité ; chacune s’ouvre d’un toucher sur l’écran concerné.\n\nLes pastilles :\n- Pistes actives : vos affaires en cours.\n- Nouvelles · 7j : les clients ajoutés ces 7 derniers jours.\n- À relancer : les affaires sans nouvelle depuis plus de 7 jours.\n- Gagnées · ce mois et Devis · ce mois.\n- Devis sans suite : émis il y a plus de 7 jours, toujours sans réponse.\n\nPlus bas : « Alertes récentes » (ce qui demande une action), « Indicateurs clés » avec le taux de conversion, et « Performance ». La cloche, en haut de l’écran, reprend les mêmes alertes.\n\nExemple — lundi matin, Ibrahim voit « À relancer : 3 ». Il touche la pastille, retrouve les trois clients et les appelle avant 10 h.\n\nErreurs fréquentes sur le terrain :\n- Ouvrir l’application seulement pour faire un devis, sans regarder les alertes.\n- Laisser grossir « Devis sans suite » : un devis oublié est souvent un client perdu.","actionTitle":"L’essentiel","actionContent":"- Une pastille d’alerte, c’est une action à faire aujourd’hui.\n- Chaque pastille ouvre l’écran concerné.\n- « À relancer » et « Devis sans suite » s’allument après 7 jours sans nouvelle."},{"id":"ad-m2-l2","title":"Les cinq onglets","type":"texte","duration":"4 min","description":"Objectif : savoir où se trouve chaque outil de l’application.","content":"Sur téléphone, cinq onglets vivent en bas de l’écran : Tableau, Suivi, Devis, Boutique et Plus. Sur ordinateur, les mêmes entrées sont dans la barre de gauche.\n\n[[schema:interface]]\n\nLe gros bouton + au centre, c’est Devis : c’est de là que part un dimensionnement solaire. Suivi clients range vos affaires par étape. La Boutique présente le catalogue et ses prix publics.\n\nPlus regroupe le reste : Clients (votre carnet d’adresses), Simulateur ROI, Formation, Mon espace partenaire et les Paramètres. Le gérant y trouve aussi Équipe, Commissions, Mes kits et Onduleurs.\n\nExemple — en visite chez un client à Abomey-Calavi, Rachidi ouvre Plus → Simulateur ROI pour lui montrer ce qu’il dépense en carburant, puis touche + pour lancer le devis.\n\nErreurs fréquentes sur le terrain :\n- Chercher ses clients dans la Boutique : ils sont dans Plus → Clients et dans Suivi clients.\n- Croire qu’un outil manque alors qu’il est réservé au gérant (Équipe, Commissions, Mes kits).","actionTitle":"L’essentiel","actionContent":"- Le + du centre : tout nouveau devis.\n- Plus → Clients : le carnet d’adresses.\n- Plus → Simulateur ROI : l’argument chiffré pour le client."},{"id":"ad-m2-quiz","title":"Quiz — L’interface","type":"quiz","duration":"2 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"ad-m2-quiz-q1","question":"Que signifie la pastille « Devis sans suite » ?","choix":["Des devis émis il y a plus de 7 jours, toujours sans réponse","Des devis refusés par le client","Des brouillons jamais envoyés"],"bonne":0,"explication":"Un devis est « sans suite » quand il a été émis il y a plus de 7 jours, qu’il est toujours en cours et qu’aucune relance n’a été faite depuis."},{"id":"ad-m2-quiz-q2","question":"Où lancer un nouveau dimensionnement solaire ?","choix":["Dans la Boutique","Dans Plus → Paramètres","Avec le bouton + au centre (Devis)"],"bonne":2,"explication":"Le + central ouvre les devis : choisissez ensuite « Dimensionnement solaire »."},{"id":"ad-m2-quiz-q3","question":"Sur téléphone, où se trouve le carnet d’adresses de vos clients ?","choix":["Dans Plus → Clients","Dans la Boutique","Dans la cloche"],"bonne":0,"explication":"Plus → Clients liste tous vos clients, avec une recherche. Les mêmes clients apparaissent aussi dans Suivi clients."},{"id":"ad-m2-quiz-q4","question":"La pastille « À relancer » affiche 4. Quelle est la bonne réaction ?","choix":["L’ignorer, ce n’est qu’un chiffre","La toucher et contacter ces clients aujourd’hui","Supprimer ces affaires"],"bonne":1,"explication":"Ce sont des affaires sans nouvelle depuis plus de 7 jours : un appel ou un message WhatsApp aujourd’hui peut les relancer."}]}]},{"id":"ad-m3","title":"Premier client, première affaire","lecons":[{"id":"ad-m3-l1","title":"Ajouter un client","type":"texte","duration":"3 min","description":"Objectif : enregistrer un client complet en moins d’une minute.","content":"Ouvrez Plus → Clients, puis touchez « Nouveau client ». Choisissez le type : particulier ou entreprise. Pour une entreprise, l’application demande aussi la personne de contact.\n\nRemplissez le nom, le téléphone, l’adresse (quartier et ville) et une note sur le besoin, puis touchez « Ajouter le client ».\n\nLe client apparaît aussitôt dans Suivi clients, à l’étape « Nouveau » : pas besoin de le créer une deuxième fois. Si son téléphone ou son e-mail existe déjà, la fiche existante est complétée au lieu d’être dupliquée.\n\nExemple — Mme Hounkpatin, atelier de couture à Parakou, quartier Zongo. Note : « coupures le soir, veut faire tourner deux machines et un ventilateur ».\n\nErreurs fréquentes sur le terrain :\n- Oublier le téléphone : impossible ensuite d’envoyer le devis sur WhatsApp.\n- Noter seulement « Maman Ablavi » sans le quartier : introuvable trois semaines plus tard.","actionTitle":"L’essentiel","actionContent":"- Un client = une fiche, visible dans Clients et dans Suivi clients.\n- Toujours le téléphone : c’est par lui que partent les devis WhatsApp.\n- La note décrit le besoin, avec les mots du client."},{"id":"ad-m3-l2","title":"Suivre l’affaire étape par étape","type":"texte","duration":"4 min","description":"Objectif : faire avancer une affaire jusqu’à la vente.","content":"Suivi clients range vos affaires en colonnes : Nouveau, Qualifié, Visite, Proposition, Négociation, Gagné. Une affaire abandonnée passe en « Perdu ».\n\nPour changer d’étape, faites glisser la carte vers la colonne suivante, ou ouvrez-la et choisissez « Déplacer vers… ». Le bouton « Nouvelle piste », en haut, crée un client directement ici.\n\n[[schema:parcours]]\n\nLa valeur de l’affaire n’est pas à saisir : elle se calcule toute seule à partir des devis du client. Notez chaque échange dans « Notes et activités » : c’est votre mémoire.\n\nExemple — après la visite chez Mme Hounkpatin, Ibrahim déplace la carte de « Qualifié » à « Visite » et note : « toit en tôle, ombre le matin côté est ».\n\nErreurs fréquentes sur le terrain :\n- Laisser tous les clients en « Nouveau » : le suivi ne sert plus à rien.\n- Passer en « Gagné » avant l’accord réel du client.","actionTitle":"L’essentiel","actionContent":"- Une étape = un vrai pas du client, pas un espoir.\n- Notez chaque appel ou visite dans la fiche.\n- « Gagné » se confirme par le gérant."},{"id":"ad-m3-quiz","title":"Quiz — Clients et affaires","type":"quiz","duration":"2 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"ad-m3-quiz-q1","question":"Vous ajoutez un client dans Plus → Clients. Faut-il aussi le créer dans Suivi clients ?","choix":["Oui, sinon il n’y apparaît pas","Non, il y apparaît déjà à l’étape « Nouveau »","Oui, avec un autre numéro"],"bonne":1,"explication":"C’est la même fiche : un client ajouté dans Clients apparaît automatiquement dans Suivi clients, à l’étape « Nouveau »."},{"id":"ad-m3-quiz-q2","question":"Quelle information ne faut-il jamais oublier sur la fiche ?","choix":["La couleur de la maison","L’âge du client","Le téléphone"],"bonne":2,"explication":"Le téléphone sert à envoyer le devis et les relances sur WhatsApp."},{"id":"ad-m3-quiz-q3","question":"Comment fixe-t-on la valeur d’une affaire ?","choix":["On la tape à la main","Elle se calcule à partir des devis du client","Le gérant la décide"],"bonne":1,"explication":"La valeur est déduite automatiquement des devis du client : il suffit de faire le devis."},{"id":"ad-m3-quiz-q4","question":"Après une visite technique, que faire ?","choix":["Déplacer la carte à « Visite » et noter ce qu’on a vu","Attendre que le client rappelle","Supprimer la fiche"],"bonne":0,"explication":"Déplacer la carte garde le suivi juste, et la note (toit, ombre, besoins) servira pour le devis."}]}]},{"id":"ad-m4","title":"Premier dimensionnement","lecons":[{"id":"ad-m4-l1","title":"À partir des appareils du client","type":"texte","duration":"4 min","description":"Objectif : obtenir le bon kit à partir de la liste des appareils du client.","content":"Touchez le + central, puis « Dimensionnement solaire ». L’assistant compte quatre étapes : Client, Consommation, Type de système, Résultat.\n\nÉtape Consommation : choisissez « Liste des appareils », puis ajoutez chaque appareil (lampes, frigo, télé, ventilateur…) avec sa quantité, sa puissance, ses heures de jour et ses heures de nuit. Un appareil absent ? « Autre appareil (non listé) ».\n\nL’application calcule la consommation de jour, de nuit, et le « Pic de charge » : tous les appareils allumés en même temps. C’est lui qui sert à choisir l’onduleur.\n\nÉtape Type de système : « Autonome (off-grid) » est proposé par défaut. Indiquez la ville du chantier (ou « Ma position ») pour l’ensoleillement, puis passez au Résultat : le kit suggéré et son prix.\n\nExemple — un salon de coiffure à Kara : 6 lampes LED, 2 sèche-cheveux, 1 ventilateur. Les sèche-cheveux font monter le pic de charge : c’est lui qui impose un onduleur assez puissant.\n\nErreurs fréquentes sur le terrain :\n- Mettre 24 h à un frigo qui tourne par cycles : la batterie est surdimensionnée.\n- Oublier un gros appareil (pompe, congélateur) : le kit lâche dès le premier soir.\n- Utiliser « Ma position » au bureau alors que le chantier est dans une autre ville.","actionTitle":"L’essentiel","actionContent":"- Les heures de NUIT décident de la batterie.\n- Le pic de charge décide de l’onduleur.\n- La ville décide de l’ensoleillement, donc des panneaux."},{"id":"ad-m4-l2","title":"À partir de la facture SBEE ou CEET","type":"texte","duration":"3 min","description":"Objectif : dimensionner quand le client ne connaît que sa facture.","content":"Le client ne sait pas lister ses appareils, mais il connaît sa facture ? À l’étape Consommation, choisissez « Facture CEET/SBEE (F CFA) ».\n\nSaisissez la « Facture mensuelle moyenne (F CFA) », vérifiez le « Prix du kWh (F CFA) » de son compteur, puis répondez à « Quand consomme-t-il le plus ? » : surtout en journée, équilibré, ou surtout le soir.\n\nCe dernier choix compte beaucoup : ce qui est consommé le soir passe par la batterie. Le même montant de facture peut donc demander un kit plus grand si le client vit surtout le soir.\n\nExemple — facture SBEE de 25 000 F par mois à 115 F le kWh : environ 217 kWh par mois, soit 7,2 kWh par jour. « Équilibré » donne une batterie conseillée d’environ 4,8 kWh ; « surtout le soir », d’environ 6,7 kWh.\n\nErreurs fréquentes sur le terrain :\n- Prendre la facture d’un mois de coupures : elle sous-estime le besoin.\n- Garder un prix du kWh qui n’est pas celui de la facture du client.","actionTitle":"L’essentiel","actionContent":"- Facture ÷ prix du kWh = la consommation du mois.\n- Prenez une facture moyenne, pas celle du mois le plus bas.\n- Le choix « surtout le soir » agrandit la batterie."},{"id":"ad-m4-quiz","title":"Quiz — Dimensionner","type":"quiz","duration":"2 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"ad-m4-quiz-q1","question":"Qu’est-ce qui décide surtout de la taille de la batterie ?","choix":["La consommation de nuit","La couleur du toit","Le nombre de prises"],"bonne":0,"explication":"La nuit, les panneaux ne produisent plus : tout ce qui est consommé passe par la batterie."},{"id":"ad-m4-quiz-q2","question":"À quoi sert le « Pic de charge » ?","choix":["À choisir la structure de montage","À calculer la facture","À choisir l’onduleur"],"bonne":2,"explication":"C’est la puissance de tous les appareils allumés ensemble : l’onduleur doit pouvoir la fournir."},{"id":"ad-m4-quiz-q3","question":"Facture de 25 000 F à 115 F le kWh : combien de kWh par mois, environ ?","choix":["22 kWh","217 kWh","2 875 kWh"],"bonne":1,"explication":"25 000 ÷ 115 ≈ 217 kWh par mois, soit environ 7,2 kWh par jour."},{"id":"ad-m4-quiz-q4","question":"Même facture, mais le client consomme surtout le soir. Que devient la batterie conseillée ?","choix":["Plus petite","Identique","Plus grande"],"bonne":2,"explication":"Ce qui est consommé le soir passe par la batterie : à facture égale, « surtout le soir » demande plus de stockage."}]}]},{"id":"ad-m5","title":"Hors ligne et synchronisation","lecons":[{"id":"ad-m5-l1","title":"Travailler sans réseau","type":"texte","duration":"3 min","description":"Objectif : continuer à travailler quand le réseau coupe, sans rien perdre.","content":"BestaSolar Pro enregistre d’abord tout sur votre téléphone. Sans réseau, vous pouvez quand même ajouter un client, faire un dimensionnement et préparer un devis.\n\nDès que le réseau revient, l’application envoie toute seule ce qui a été fait. Le gérant en voit l’état dans Plus : « Données partagées en temps réel » quand tout est parti, sinon « Hors ligne — le travail est enregistré ici », avec le nombre d’éléments en attente d’envoi.\n\nHors ligne, l’ensoleillement de la ville ne peut pas être téléchargé : utilisez « Saisie manuelle (hors-ligne) » à l’étape Type de système.\n\nPour que l’envoi se fasse, rouvrez simplement l’application une fois revenu en zone couverte. Ne la désinstallez jamais avant : ce qui n’est pas encore envoyé n’existe que sur ce téléphone.\n\nExemple — en brousse près de Bassila, aucune barre de réseau. Adjoa enregistre deux clients et leurs dimensionnements. Le soir, de retour à Djougou, tout part sur le serveur en quelques secondes.\n\nErreurs fréquentes sur le terrain :\n- Refaire un devis en double parce que le gérant ne le voit pas encore : attendez le retour du réseau.\n- Vider les données ou désinstaller l’application avec des éléments en attente d’envoi.","actionTitle":"L’essentiel","actionContent":"- Sans réseau, on travaille normalement.\n- Le retour du réseau envoie tout, tout seul.\n- Jamais de désinstallation avant l’envoi."},{"id":"ad-m5-l2","title":"Sauvegarder ses données","type":"texte","duration":"2 min","description":"Objectif : garder une copie de secours de toutes les données.","content":"Le gérant peut télécharger une copie complète : Plus → Sauvegarde des données → « Exporter (télécharger) ». Gardez ce fichier ailleurs que sur le téléphone : ordinateur, clé USB ou e-mail.\n\n« Importer (restaurer) » remet une sauvegarde en place. Attention : l’import remplace les données actuelles. Exportez toujours d’abord, par sécurité.\n\nExemple — chaque fin de mois, M. Kodjo exporte sa sauvegarde et l’envoie sur sa propre adresse e-mail.\n\nErreurs fréquentes sur le terrain :\n- Importer une vieille sauvegarde par-dessus des données récentes.\n- Garder la sauvegarde uniquement sur le téléphone qu’on risque de perdre.","actionTitle":"L’essentiel","actionContent":"- Une sauvegarde par mois, au minimum.\n- Exporter avant d’importer, toujours.\n- Le fichier se garde ailleurs que sur le téléphone."},{"id":"ad-m5-quiz","title":"Quiz — Hors ligne","type":"quiz","duration":"2 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"ad-m5-quiz-q1","question":"Le réseau coupe pendant une visite. Que faire ?","choix":["Arrêter et revenir plus tard","Continuer : tout est enregistré sur le téléphone","Noter sur papier puis tout ressaisir"],"bonne":1,"explication":"L’application enregistre d’abord sur le téléphone, puis envoie tout au retour du réseau."},{"id":"ad-m5-quiz-q2","question":"Quand ne faut-il surtout pas désinstaller l’application ?","choix":["Après une mise à jour","Le dimanche","Quand des éléments sont en attente d’envoi"],"bonne":2,"explication":"Ce qui n’est pas encore envoyé n’existe que sur ce téléphone : le désinstaller l’effacerait."},{"id":"ad-m5-quiz-q3","question":"Avant d’« Importer (restaurer) » une sauvegarde, que faut-il faire ?","choix":["Rien","Exporter d’abord les données actuelles","Désinstaller l’application"],"bonne":1,"explication":"L’import remplace les données actuelles : une exportation préalable évite toute perte."}]}]},{"id":"ad-final","title":"Quiz final","lecons":[{"id":"ad-final-quiz","title":"Quiz final — Démarrer avec BestaSolar Pro","type":"quiz","duration":"3 min","description":"Cinq questions sur toute la formation. Chaque réponse est expliquée.","questions":[{"id":"ad-final-quiz-q1","question":"Quelles informations demande l’inscription ?","choix":["Nom, téléphone, e-mail, mot de passe et code partenaire facultatif","Seulement le téléphone","Une pièce d’identité"],"bonne":0,"explication":"Cinq champs, dont le code partenaire facultatif : le pays se choisit dans le champ téléphone."},{"id":"ad-final-quiz-q2","question":"Qui valide le passage d’une affaire à « Gagné » ?","choix":["Le client","Le gérant","Personne"],"bonne":1,"explication":"Le changement d’étape d’un technicien vers « Gagné » est soumis à la validation du gérant."},{"id":"ad-final-quiz-q3","question":"Un client ajouté dans Plus → Clients apparaît aussi…","choix":["Nulle part ailleurs","Dans la Boutique","Dans Suivi clients, à l’étape « Nouveau »"],"bonne":2,"explication":"Clients et Suivi clients montrent la même fiche."},{"id":"ad-final-quiz-q4","question":"Le client ne connaît que sa facture SBEE. Quel mode de consommation choisir ?","choix":["Liste des appareils","Facture CEET/SBEE (F CFA)","Saisie directe (kWh)"],"bonne":1,"explication":"Le mode facture convertit le montant mensuel en kWh avec le prix du kWh."},{"id":"ad-final-quiz-q5","question":"Que se passe-t-il quand le réseau revient après une journée hors ligne ?","choix":["Il faut tout ressaisir","Les données sont perdues","L’application envoie tout, toute seule"],"bonne":2,"explication":"Tout ce qui a été fait hors ligne part automatiquement au retour du réseau."}]}]}]},
{"id":"academie-devis","title":"Créer des devis qui signent","author":"Académie BestaSolar","description":"Du dimensionnement au devis signé : composer, présenter la fiche et le Simulateur ROI, envoyer, relancer — et personnaliser vos documents avec l’offre Pro. Niveau intermédiaire.","cover":"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%201600%20900%22%3E%20%3Cdefs%3E%3ClinearGradient%20id%3D%22g%22%20x1%3D%220%22%20y1%3D%220%22%20x2%3D%221%22%20y2%3D%221%22%3E%3Cstop%20offset%3D%220%22%20stop-color%3D%22%2308215A%22%2F%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%230D3483%22%2F%3E%3C%2FlinearGradient%3E%3C%2Fdefs%3E%20%3Crect%20width%3D%221600%22%20height%3D%22900%22%20fill%3D%22url(%23g)%22%2F%3E%20%3Ccircle%20cx%3D%221480%22%20cy%3D%22120%22%20r%3D%22260%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.05%22%2F%3E%20%3Ccircle%20cx%3D%22120%22%20cy%3D%22860%22%20r%3D%22220%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.05%22%2F%3E%20%3Ctext%20x%3D%22110%22%20y%3D%22400%22%20fill%3D%22%23FFA800%22%20font-family%3D%22Arial%2C%20Helvetica%2C%20sans-serif%22%20font-size%3D%2224%22%20font-weight%3D%22700%22%20letter-spacing%3D%224%22%3EACAD%C3%89MIE%20BESTASOLAR%3C%2Ftext%3E%20%3Ctext%20x%3D%22110%22%20y%3D%22455%22%20fill%3D%22%23ffffff%22%20font-family%3D%22Arial%2C%20Helvetica%2C%20sans-serif%22%20font-size%3D%2258%22%20font-weight%3D%22700%22%3ECr%C3%A9er%20des%20devis%3C%2Ftext%3E%3Ctext%20x%3D%22110%22%20y%3D%22515%22%20fill%3D%22%23ffffff%22%20font-family%3D%22Arial%2C%20Helvetica%2C%20sans-serif%22%20font-size%3D%2258%22%20font-weight%3D%22700%22%3Equi%20signent%3C%2Ftext%3E%20%3Cg%20transform%3D%22translate(1060%20210)%20rotate(-6)%22%3E%20%3Crect%20width%3D%22330%22%20height%3D%22430%22%20rx%3D%2216%22%20fill%3D%22%23ffffff%22%2F%3E%20%3Crect%20x%3D%2234%22%20y%3D%2240%22%20width%3D%22150%22%20height%3D%2226%22%20rx%3D%226%22%20fill%3D%22%230D3483%22%2F%3E%20%3Crect%20x%3D%22226%22%20y%3D%2240%22%20width%3D%2270%22%20height%3D%2226%22%20rx%3D%226%22%20fill%3D%22%23FFA800%22%2F%3E%20%3Crect%20x%3D%2234%22%20y%3D%22110%22%20width%3D%22200%22%20height%3D%2214%22%20rx%3D%224%22%20fill%3D%22%230D3483%22%20opacity%3D%22.22%22%2F%3E%3Crect%20x%3D%22250%22%20y%3D%22110%22%20width%3D%2246%22%20height%3D%2214%22%20rx%3D%224%22%20fill%3D%22%230D3483%22%20opacity%3D%22.35%22%2F%3E%3Crect%20x%3D%2234%22%20y%3D%22150%22%20width%3D%22200%22%20height%3D%2214%22%20rx%3D%224%22%20fill%3D%22%230D3483%22%20opacity%3D%22.22%22%2F%3E%3Crect%20x%3D%22250%22%20y%3D%22150%22%20width%3D%2246%22%20height%3D%2214%22%20rx%3D%224%22%20fill%3D%22%230D3483%22%20opacity%3D%22.35%22%2F%3E%3Crect%20x%3D%2234%22%20y%3D%22190%22%20width%3D%22200%22%20height%3D%2214%22%20rx%3D%224%22%20fill%3D%22%230D3483%22%20opacity%3D%22.22%22%2F%3E%3Crect%20x%3D%22250%22%20y%3D%22190%22%20width%3D%2246%22%20height%3D%2214%22%20rx%3D%224%22%20fill%3D%22%230D3483%22%20opacity%3D%22.35%22%2F%3E%3Crect%20x%3D%2234%22%20y%3D%22230%22%20width%3D%22200%22%20height%3D%2214%22%20rx%3D%224%22%20fill%3D%22%230D3483%22%20opacity%3D%22.22%22%2F%3E%3Crect%20x%3D%22250%22%20y%3D%22230%22%20width%3D%2246%22%20height%3D%2214%22%20rx%3D%224%22%20fill%3D%22%230D3483%22%20opacity%3D%22.35%22%2F%3E%3Crect%20x%3D%2234%22%20y%3D%22270%22%20width%3D%22200%22%20height%3D%2214%22%20rx%3D%224%22%20fill%3D%22%230D3483%22%20opacity%3D%22.22%22%2F%3E%3Crect%20x%3D%22250%22%20y%3D%22270%22%20width%3D%2246%22%20height%3D%2214%22%20rx%3D%224%22%20fill%3D%22%230D3483%22%20opacity%3D%22.35%22%2F%3E%20%3Crect%20x%3D%2234%22%20y%3D%22320%22%20width%3D%22262%22%20height%3D%223%22%20fill%3D%22%230D3483%22%20opacity%3D%22.3%22%2F%3E%20%3Crect%20x%3D%22150%22%20y%3D%22342%22%20width%3D%22146%22%20height%3D%2234%22%20rx%3D%228%22%20fill%3D%22%230D3483%22%2F%3E%20%3Cpath%20d%3D%22M40%20398%20q24%20-28%2048%200%20t48%200%22%20stroke%3D%22%230D3483%22%20stroke-width%3D%225%22%20fill%3D%22none%22%20stroke-linecap%3D%22round%22%2F%3E%20%3C%2Fg%3E%20%3Cg%20transform%3D%22translate(1310%20380)%20rotate(38)%22%3E%20%3Crect%20width%3D%2234%22%20height%3D%22300%22%20rx%3D%2210%22%20fill%3D%22%23FFA800%22%2F%3E%20%3Crect%20y%3D%22230%22%20width%3D%2234%22%20height%3D%2238%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.85%22%2F%3E%20%3Cpath%20d%3D%22M0%20300%20L17%20352%20L34%20300%20Z%22%20fill%3D%22%23ffffff%22%2F%3E%20%3Cpath%20d%3D%22M11%20334%20L17%20352%20L23%20334%20Z%22%20fill%3D%22%2308215A%22%2F%3E%20%3C%2Fg%3E%20%3C%2Fsvg%3E","modules":[{"id":"dv-m1","title":"Anatomie d’un bon devis solaire","lecons":[{"id":"dv-m1-l1","title":"Ce que le client doit lire","type":"texte","duration":"5 min","description":"Objectif : savoir ce qu’un devis solaire doit contenir pour rassurer le client.","content":"Un bon devis répond à trois questions : qu’est-ce que j’achète, combien ça coûte en tout, et que se passe-t-il après ? Le devis de l’application range tout en deux blocs : « Équipements » et « Prestations ».\n\nÉquipements : panneaux, onduleur hybride, batterie, protections et câbles, chacun avec sa quantité et son prix. Prestations : la main-d’œuvre de pose. Le total TTC conclut.\n\n[[schema:kit]]\n\nCe schéma, expliquez-le avec le devis : les panneaux produisent, le régulateur MPPT de l’onduleur hybride en tire le maximum, la batterie stocke pour la nuit, et la maison reçoit du 230 V.\n\nLe bas du document porte les conditions : le devis est valable 30 jours, et la livraison se fait après réception de l’acompte convenu. Parlez aussi de la garantie de chaque équipement : c’est souvent elle qui décide le client.\n\nExemple — face à un commerçant de Dantokpa qui compare avec un « kit pas cher » du marché, montrez ligne par ligne : batterie lithium, onduleur hybride, protections DC/AC, pose incluse. Le prix bas d’en face oublie souvent les protections et la pose.\n\nErreurs fréquentes sur le terrain :\n- Envoyer un devis sans l’expliquer : le client ne compare que le total.\n- Promettre une garantie que le fournisseur ne donne pas.\n- Oublier la pose dans le prix annoncé à l’oral.","actionTitle":"L’essentiel","actionContent":"- Équipements + Prestations = le total, sans surprise.\n- Expliquez le chemin : panneaux → MPPT → onduleur → batterie → maison.\n- Validité de 30 jours : rappelez-la, elle crée l’urgence."},{"id":"dv-m1-quiz","title":"Quiz — Le bon devis","type":"quiz","duration":"3 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"dv-m1-quiz-q1","question":"Dans le devis de l’application, où se trouve la main-d’œuvre de pose ?","choix":["Elle n’apparaît pas","Dans « Équipements »","Dans « Prestations »"],"bonne":2,"explication":"La pose est une prestation : elle est séparée du matériel pour que le client voie ce qu’il paie."},{"id":"dv-m1-quiz-q2","question":"Quel élément tire le maximum d’énergie des panneaux ?","choix":["La batterie","Le régulateur MPPT de l’onduleur hybride","Le coffret AC"],"bonne":1,"explication":"Le MPPT, intégré à l’onduleur hybride, ajuste en permanence le point de fonctionnement des panneaux."},{"id":"dv-m1-quiz-q3","question":"Combien de temps un devis est-il valable par défaut ?","choix":["7 jours","30 jours","1 an"],"bonne":1,"explication":"Les conditions du devis indiquent une validité de 30 jours."},{"id":"dv-m1-quiz-q4","question":"Le client compare votre total avec un kit moins cher du marché. Votre meilleure réponse ?","choix":["Baisser votre prix tout de suite","Abandonner l’affaire","Montrer ligne par ligne ce que contient votre devis (protections, pose…)"],"bonne":2,"explication":"Le client compare souvent un kit incomplet à une installation complète : le détail du devis le montre."}]}]},{"id":"dv-m2","title":"Du dimensionnement au devis","lecons":[{"id":"dv-m2-l1","title":"Le kit suggéré","type":"texte","duration":"6 min","description":"Objectif : transformer un dimensionnement en devis chiffré, en quelques touches.","content":"À l’étape Résultat, l’application propose le kit le mieux adapté : la plus petite batterie qui couvre la nuit. Si plusieurs kits ont la même capacité, ils sont tous proposés : choisissez la marque ou la composition.\n\nLe nombre de panneaux est ajusté au besoin réel du client. Si l’onduleur du kit ne suffit pas pour ces panneaux, l’application en retient un adapté et l’explique dans un encadré.\n\nRéglez ensuite le « Type de support » (Tôle, Dalle, Au sol) et le « Réseau électrique » (Monophasé ou Triphasé). Cochez « Client a son propre soudeur » si la structure ne doit pas figurer au devis.\n\n[[schema:flux-devis]]\n\nVérifiez les blocs Équipements et Prestations et le « Total TTC », puis touchez « Créer le devis pour … ». Il reçoit un numéro du type BS-20261015-0001.\n\nExemple — pour un ménage de Porto-Novo, deux kits de 5 kWh sont proposés à des prix différents. Odile montre les deux au client, qui choisit la version qui lui convient.\n\nErreurs fréquentes sur le terrain :\n- Ignorer l’encadré « Pic de consommation » : le client risque de faire disjoncter son onduleur.\n- Laisser « Tôle » pour une pose sur dalle : le prix de la structure est faux.","actionTitle":"L’essentiel","actionContent":"- Le kit est choisi sur la batterie, les panneaux sur le besoin.\n- Le support change le prix : tôle, dalle ou au sol.\n- Lisez toujours les encadrés : onduleur changé, pic non couvert."},{"id":"dv-m2-l2","title":"Brouillon, devis finalisé, devis à revoir","type":"texte","duration":"4 min","description":"Objectif : choisir le bon statut et corriger un devis sans le refaire.","content":"En bas de l’assistant, deux boutons : « Brouillon » garde le devis pour plus tard ; « Créer le devis » le finalise. Un brouillon n’est jamais compté parmi les devis sans suite.\n\nDans l’onglet Devis, touchez un devis pour ouvrir ses actions : « Envoyer le devis sur WhatsApp », « Fiche de dimensionnement (PDF) », « Relancer par WhatsApp » et, pour un devis solaire, « Revoir le dimensionnement ».\n\n« Revoir le dimensionnement » rouvre l’étude avec tous les appareils : retirez un congélateur, et le même devis est mis à jour, avec le même numéro. Un brouillon, lui, se valide avec « Finaliser ».\n\nExemple — le client de Bohicon renonce au congélateur. Au lieu de tout ressaisir, Serge ouvre « Revoir le dimensionnement », retire l’appareil, et le devis se recalcule avec un kit plus petit.\n\nErreurs fréquentes sur le terrain :\n- Créer un nouveau devis à chaque modification : le client reçoit trois numéros différents.\n- Envoyer un brouillon sans l’avoir vérifié.","actionTitle":"L’essentiel","actionContent":"- Brouillon = pas encore montré au client.\n- « Revoir le dimensionnement » corrige sans dupliquer.\n- Un devis garde son numéro du début à la fin."},{"id":"dv-m2-quiz","title":"Quiz — Du dimensionnement au devis","type":"quiz","duration":"3 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"dv-m2-quiz-q1","question":"Sur quoi l’application choisit-elle le kit suggéré ?","choix":["Sur la plus petite batterie qui couvre la nuit","Sur le kit le plus cher","Au hasard"],"bonne":0,"explication":"Le kit se choisit sur sa batterie ; les panneaux sont ensuite ajustés au besoin réel."},{"id":"dv-m2-quiz-q2","question":"Le client a déjà sa structure de montage. Que faites-vous ?","choix":["Rien, la structure reste au devis","Choisir « Au sol »","Cocher « Client a son propre soudeur »"],"bonne":2,"explication":"Cette case retire la ligne « Structure de montage » du devis."},{"id":"dv-m2-quiz-q3","question":"Le client change d’avis sur un appareil. Le bon geste ?","choix":["Refaire un devis neuf","« Revoir le dimensionnement » sur le même devis","Supprimer le client"],"bonne":1,"explication":"Le même devis est recalculé, avec le même numéro : le client ne reçoit pas plusieurs devis."},{"id":"dv-m2-quiz-q4","question":"Un brouillon peut-il apparaître dans « Devis sans suite » ?","choix":["Oui, après 7 jours","Non, seuls les devis émis y apparaissent"],"bonne":1,"explication":"Un brouillon n’a jamais été montré au client : il ne peut pas être « sans suite »."}]}]},{"id":"dv-m3","title":"Présenter la fiche de dimensionnement","lecons":[{"id":"dv-m3-l1","title":"La fiche en trois pages","type":"texte","duration":"5 min","description":"Objectif : présenter la fiche technique pour justifier le prix.","content":"La « Fiche de dimensionnement (PDF) » est l’étude technique du besoin du client. Elle se produit depuis l’étape Résultat de l’assistant, ou depuis les actions d’un devis.\n\nElle tient en trois pages : la page 1 liste les appareils du client et met en avant la puissance des panneaux, en kWc ; la page 2 donne les paramètres, le matériel et les résultats ; la page 3, l’analyse.\n\nLa page 3 est celle qui convainc : la « Production mensuelle » sur l’année, l’« Économie annuelle », le « Retour sur investissement » et la maintenance prévue. Commencez par elle quand le client hésite.\n\nExemple — M. Gbaguidi trouve le kit cher. Sylvie lui montre la page 3 : l’économie annuelle et le nombre d’années pour rembourser l’installation. La discussion passe du prix au placement.\n\nErreurs fréquentes sur le terrain :\n- Envoyer la fiche sans la commenter : le client ne lit que le total.\n- Annoncer une économie différente de celle de la fiche.","actionTitle":"L’essentiel","actionContent":"- Page 1 : le besoin du client.\n- Page 2 : le matériel et les résultats.\n- Page 3 : l’argent — économie et retour sur investissement."},{"id":"dv-m3-l2","title":"Le Simulateur ROI face au client","type":"texte","duration":"5 min","description":"Objectif : montrer au client ce qu’il paie déjà, réseau et groupe électrogène compris.","content":"Plus → Simulateur ROI part de ce que le client paie aujourd’hui. Saisissez sa consommation « D’après ses appareils » ou « D’après sa facture », puis le pays : le prix du kWh de l’opérateur (SBEE, CEET, CIE…) se règle tout seul.\n\nIndiquez les « Coupures de courant » en heures par jour et cochez « Le client a un groupe électrogène », avec le prix du litre de gazole. L’écran compare alors le kWh au réseau et le kWh au groupe.\n\nEn face, l’application place le kit qu’elle proposerait, avec son prix. Elle affiche le temps pour rembourser l’installation, l’économie de la 1re année et le gain sur la durée choisie : 10, 15 ou 25 ans.\n\nEn bas, « Ce que le calcul suppose » liste les hypothèses. Lisez-les : un chiffre qu’on ne sait pas justifier ne vaut rien devant le client.\n\nExemple — facture SBEE de 25 000 F, 4 h de coupure par jour, gazole à 750 F le litre : le kWh du groupe revient à 250 F, contre 115 F au réseau. Le client comprend pourquoi ses dépenses explosent pendant les coupures.\n\nErreurs fréquentes sur le terrain :\n- Annoncer un remboursement plus rapide que celui affiché.\n- Oublier les coupures : on sous-estime ce que le client dépense déjà.","actionTitle":"L’essentiel","actionContent":"- Partez de ce que le client paie déjà.\n- Le kWh au groupe coûte souvent plus du double du réseau.\n- Choisissez la durée avec le client : 10, 15 ou 25 ans."},{"id":"dv-m3-quiz","title":"Quiz — Présenter les chiffres","type":"quiz","duration":"3 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"dv-m3-quiz-q1","question":"Quelle page de la fiche montre l’économie annuelle et le retour sur investissement ?","choix":["La page 1","La page 2","La page 3"],"bonne":2,"explication":"La page 3, l’analyse, porte la production mensuelle, l’économie annuelle et le retour sur investissement."},{"id":"dv-m3-quiz-q2","question":"Gazole à 750 F le litre : combien coûte environ un kWh produit par le groupe ?","choix":["75 F","250 F","750 F"],"bonne":1,"explication":"Un groupe tire environ 3 kWh d’un litre : 750 ÷ 3 = 250 F le kWh, plus du double du réseau."},{"id":"dv-m3-quiz-q3","question":"Où trouver les hypothèses du Simulateur ROI ?","choix":["Dans « Ce que le calcul suppose »","Nulle part","Dans la Boutique"],"bonne":0,"explication":"Toutes les hypothèses y sont écrites, pour pouvoir les expliquer au client."},{"id":"dv-m3-quiz-q4","question":"Le client hésite sur le prix. Par quoi commencer ?","choix":["Baisser le prix","Parler d’un autre client","La page 3 de la fiche : économie et retour sur investissement"],"bonne":2,"explication":"Montrer ce que l’installation fait économiser change la question : le client compare un placement, plus un prix."}]}]},{"id":"dv-m4","title":"Envoyer, relancer, suivre","lecons":[{"id":"dv-m4-l1","title":"Envoyer le devis sur WhatsApp","type":"texte","duration":"4 min","description":"Objectif : faire arriver le devis chez le client, en PDF, au bon moment.","content":"Dans l’onglet Devis, touchez le devis puis « Envoyer le devis sur WhatsApp ». Le PDF est préparé et joint directement à la conversation du client.\n\nEnvoyez-le pendant que l’intérêt est chaud : idéalement le jour de la visite. Ajoutez un message court qui reprend le besoin du client, avec ses mots.\n\nLa « Fiche de dimensionnement (PDF) » se produit au même endroit. Pour garder le devis ou l’imprimer, il peut aussi être téléchargé en PDF.\n\nExemple — message d’Ibrahim : « Bonsoir Mme Hounkpatin, voici le devis pour vos deux machines et le ventilateur, même pendant les coupures du soir. Je passe mardi répondre à vos questions. »\n\nErreurs fréquentes sur le terrain :\n- Envoyer le devis sans un mot : il se perd dans la conversation.\n- Attendre une semaine « pour laisser réfléchir ».","actionTitle":"L’essentiel","actionContent":"- Le jour même de la visite, si possible.\n- Un message court qui reprend le besoin du client.\n- Proposez une date de rappel dans le message."},{"id":"dv-m4-l2","title":"Gérer les devis sans suite","type":"texte","duration":"5 min","description":"Objectif : relancer au bon moment, sans harceler.","content":"Un devis devient « sans suite » quand il a été émis il y a plus de 7 jours, qu’il est toujours en cours et qu’il n’a pas été relancé depuis. Le tableau de bord le compte dans la pastille « Devis sans suite ».\n\nTouchez cette pastille : l’onglet Devis s’ouvre sur le filtre « Sans suite ». Pour chaque devis, « Relancer par WhatsApp » ouvre un message déjà rédigé, avec le numéro du devis, son montant et sa date de fin de validité.\n\nLa relance est notée sur le devis (« Dernière relance ») et il quitte la liste des sans suite. Si le client dit non, passez l’affaire en « Perdu » : un tableau propre vaut mieux qu’un faux espoir.\n\nExemple — le devis BS-20261002-0004 de 1 180 000 F dort depuis 9 jours. Odile touche « Relancer par WhatsApp » ; le client répond le soir même : il attendait sa paie de fin de mois.\n\nErreurs fréquentes sur le terrain :\n- Relancer tous les jours : le client finit par bloquer votre numéro.\n- Laisser des affaires mortes gonfler le compteur au lieu de les passer en « Perdu ».","actionTitle":"L’essentiel","actionContent":"- 7 jours sans nouvelle : on relance.\n- Le message de relance est déjà rédigé.\n- Un « non » se range en « Perdu »."},{"id":"dv-m4-quiz","title":"Quiz — Envoyer et relancer","type":"quiz","duration":"3 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"dv-m4-quiz-q1","question":"Quand un devis devient-il « sans suite » ?","choix":["Dès son envoi","Émis depuis plus de 7 jours, en cours, sans relance","Quand le client dit non"],"bonne":1,"explication":"Les trois conditions ensemble : plus de 7 jours, toujours en cours, aucune relance depuis l’envoi."},{"id":"dv-m4-quiz-q2","question":"Que contient le message de « Relancer par WhatsApp » ?","choix":["Rien, il faut tout écrire","Une publicité","Le numéro du devis, son montant et sa date de fin de validité"],"bonne":2,"explication":"Le message est pré-rempli : vous pouvez le personnaliser avant de l’envoyer."},{"id":"dv-m4-quiz-q3","question":"Le meilleur moment pour envoyer le devis ?","choix":["Le jour de la visite","Un mois après","Jamais par WhatsApp"],"bonne":0,"explication":"Le jour même, le client a encore la visite en tête et ses questions fraîches."},{"id":"dv-m4-quiz-q4","question":"Le client refuse définitivement. Que faire ?","choix":["Le relancer chaque jour","Passer l’affaire en « Perdu »","Supprimer son numéro"],"bonne":1,"explication":"« Perdu » garde la trace de l’affaire et laisse vos indicateurs justes."}]}]},{"id":"dv-m5","title":"Personnaliser ses devis avec l’offre Pro","lecons":[{"id":"dv-m5-l1","title":"Vos documents à votre nom","type":"texte","duration":"5 min","description":"Objectif : savoir ce que l’offre Pro change pour vos devis et vos factures.","content":"L’offre Pro (« Abonnement Devis Pro », dans Plus) vous donne votre propre espace : vos clients, vos devis et vos factures, à l’identité de VOTRE entreprise. Le dimensionnement et le suivi clients restent gratuits, avec ou sans Pro.\n\nDans « Mon entreprise » : ajoutez votre logo (« Ajouter mon logo »), le nom et le slogan, vos coordonnées et le pays, puis choisissez le « Modèle de document » : Studio, Vague ou Sobre. Les couleurs sont détectées sur votre logo, et ajustables.\n\nVous réglez aussi le préfixe des factures, votre numéro Mobile Money pour être payé, et les « Mentions / conditions (bas de document) » : c’est là que vous écrivez votre garantie.\n\nTrois formules : Pro Essentiel à 5 000 F par mois, Pro Confort à 12 750 F pour 3 mois, Pro Premium à 45 000 F par an, réglées par Mobile Money.\n\nExemple — « Soleil d’Atakora », petite entreprise de Natitingou, envoie désormais ses devis à son logo jaune et vert. Ses clients reconnaissent son entreprise du premier coup d’œil.\n\nErreurs fréquentes sur le terrain :\n- Un logo flou, pris en photo : utilisez un fichier PNG ou JPG, fond transparent conseillé.\n- Oublier le numéro Mobile Money : le client ne sait pas comment payer.","actionTitle":"L’essentiel","actionContent":"- Pro = vos documents à votre nom, avec votre logo et vos couleurs.\n- La garantie s’écrit dans les mentions du bas de document.\n- Le dimensionnement reste gratuit, avec ou sans Pro."},{"id":"dv-m5-quiz","title":"Quiz — L’offre Pro","type":"quiz","duration":"2 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"dv-m5-quiz-q1","question":"Où écrire la garantie qui apparaîtra sur vos documents Pro ?","choix":["Dans « Mentions / conditions (bas de document) »","Dans le nom de l’entreprise","On ne peut pas"],"bonne":0,"explication":"Ces mentions s’impriment en bas de chaque devis et de chaque facture."},{"id":"dv-m5-quiz-q2","question":"Combien coûte la formule Pro Essentiel ?","choix":["Elle est gratuite","5 000 F par mois","45 000 F par mois"],"bonne":1,"explication":"Pro Essentiel : 5 000 F par mois. Pro Confort : 12 750 F pour 3 mois. Pro Premium : 45 000 F par an."},{"id":"dv-m5-quiz-q3","question":"Sans abonnement Pro, le dimensionnement solaire est-il disponible ?","choix":["Oui, il reste gratuit","Non"],"bonne":0,"explication":"Le dimensionnement, les devis et le suivi clients sont gratuits ; Pro ajoute vos documents à votre nom."}]}]},{"id":"dv-ex","title":"Exercice pratique : un ménage à Parakou","lecons":[{"id":"dv-ex-l1","title":"Le cas complet, de la facture à la relance","type":"texte","duration":"8 min","description":"Objectif : dérouler un dossier complet, de la facture au devis relancé.","content":"Le cas : M. et Mme Bio, à Parakou, quartier Banikanni. Facture SBEE d’environ 25 000 F par mois. Télé et ventilateurs tournent surtout le soir, et les coupures sont fréquentes.\n\nÉtape 1 — Créez le client (Plus → Clients → « Nouveau client »), avec le téléphone et le quartier. Notez : « coupures le soir, facture 25 000 F ».\n\nÉtape 2 — Touchez +, puis « Dimensionnement solaire ». Choisissez le client, puis « Facture CEET/SBEE (F CFA) » : 25 000 F, prix du kWh 115 F. Essayez « Équilibré », puis « Surtout le soir », et comparez.\n\nCe que vous devez trouver : environ 217 kWh par mois, soit 7,2 kWh par jour. En « Équilibré », une batterie conseillée d’environ 4,8 kWh ; en « Surtout le soir », d’environ 6,7 kWh, donc un kit plus grand.\n\nÉtape 3 — À l’étape Résultat, notez le kit suggéré et son total. Avec les kits livrés par défaut dans l’application : le Kit 5 kWh en « Équilibré », le Kit 10 kWh en « Surtout le soir ». Vos montants suivent les kits de votre entreprise.\n\nÉtape 4 — Ouvrez Plus → Simulateur ROI avec la même facture, 4 h de coupure et un groupe électrogène : montrez au couple le prix du kWh au groupe face au réseau.\n\nÉtape 5 — Créez le devis, envoyez-le sur WhatsApp le jour même avec la fiche de dimensionnement, et proposez une date de rappel. Sans réponse après 7 jours : « Relancer par WhatsApp ».\n\nExemple — comme le couple vit surtout le soir, Odile retient « Surtout le soir ». Le kit est plus grand, mais la batterie tient jusqu’au matin : c’est ce qu’elle explique avec la page 3 de la fiche.\n\nErreurs fréquentes sur le terrain :\n- Dimensionner en « Équilibré » un ménage qui vit le soir : la batterie est vide avant minuit.\n- Annoncer un prix avant d’avoir vu le résultat de l’assistant.","actionTitle":"L’essentiel","actionContent":"- La répartition jour/soir change le kit : posez la question.\n- Fiche + Simulateur ROI = l’argument chiffré.\n- Envoi le jour même, relance à 7 jours."},{"id":"dv-final-quiz","title":"Quiz final — Créer des devis qui signent","type":"quiz","duration":"4 min","description":"Cinq questions sur toute la formation, dont le cas de Parakou. Chaque réponse est expliquée.","questions":[{"id":"dv-final-quiz-q1","question":"Facture SBEE de 25 000 F à 115 F le kWh : consommation par jour, environ ?","choix":["2,4 kWh","7,2 kWh","21,7 kWh"],"bonne":1,"explication":"25 000 ÷ 115 ≈ 217 kWh par mois ; divisé par 30 jours, environ 7,2 kWh par jour."},{"id":"dv-final-quiz-q2","question":"Le couple vit surtout le soir. Par rapport à « Équilibré », le kit…","choix":["est plus petit","est le même","est plus grand (batterie plus grosse)"],"bonne":2,"explication":"La consommation du soir passe par la batterie : il en faut une plus grosse."},{"id":"dv-final-quiz-q3","question":"Quel document montre l’économie annuelle et le retour sur investissement ?","choix":["La Boutique","Le reçu Mobile Money","La page 3 de la fiche de dimensionnement"],"bonne":2,"explication":"La page 3 de la fiche, l’analyse, porte l’économie annuelle et le retour sur investissement."},{"id":"dv-final-quiz-q4","question":"Sans nouvelle 7 jours après l’envoi, que faire ?","choix":["« Relancer par WhatsApp »","Refaire un devis","Attendre un mois"],"bonne":0,"explication":"Le message de relance est déjà rédigé, et la relance est notée sur le devis."},{"id":"dv-final-quiz-q5","question":"Avec l’offre Pro, où écrit-on sa garantie ?","choix":["Dans « Mentions / conditions (bas de document) »","Dans le nom du client","Dans le préfixe des factures"],"bonne":0,"explication":"Ces mentions apparaissent en bas de chaque devis et facture Pro."}]}]}]},
{"id":"academie-revenus","title":"Gagner de l’argent avec BestaSolar Pro","author":"Académie BestaSolar","description":"Les sources de revenus d’une vente solaire, trouver ses clients, piloter son activité avec le tableau de bord, fidéliser — et un plan d’action sur 30 jours. Niveau intermédiaire.","cover":"data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%201600%20900%22%3E%20%3Cdefs%3E%3ClinearGradient%20id%3D%22g%22%20x1%3D%220%22%20y1%3D%220%22%20x2%3D%221%22%20y2%3D%221%22%3E%3Cstop%20offset%3D%220%22%20stop-color%3D%22%2308215A%22%2F%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%230D3483%22%2F%3E%3C%2FlinearGradient%3E%3C%2Fdefs%3E%20%3Crect%20width%3D%221600%22%20height%3D%22900%22%20fill%3D%22url(%23g)%22%2F%3E%20%3Ccircle%20cx%3D%221480%22%20cy%3D%22120%22%20r%3D%22260%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.05%22%2F%3E%20%3Ccircle%20cx%3D%22120%22%20cy%3D%22860%22%20r%3D%22220%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.05%22%2F%3E%20%3Ctext%20x%3D%22110%22%20y%3D%22400%22%20fill%3D%22%23FFA800%22%20font-family%3D%22Arial%2C%20Helvetica%2C%20sans-serif%22%20font-size%3D%2224%22%20font-weight%3D%22700%22%20letter-spacing%3D%224%22%3EACAD%C3%89MIE%20BESTASOLAR%3C%2Ftext%3E%20%3Ctext%20x%3D%22110%22%20y%3D%22455%22%20fill%3D%22%23ffffff%22%20font-family%3D%22Arial%2C%20Helvetica%2C%20sans-serif%22%20font-size%3D%2258%22%20font-weight%3D%22700%22%3EGagner%20de%20l%E2%80%99argent%3C%2Ftext%3E%3Ctext%20x%3D%22110%22%20y%3D%22515%22%20fill%3D%22%23ffffff%22%20font-family%3D%22Arial%2C%20Helvetica%2C%20sans-serif%22%20font-size%3D%2258%22%20font-weight%3D%22700%22%3Eavec%20BestaSolar%20Pro%3C%2Ftext%3E%20%3Cellipse%20cx%3D%221110%22%20cy%3D%22660%22%20rx%3D%2292%22%20ry%3D%2228%22%20fill%3D%22%23FFA800%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%225%22%2F%3E%3Cellipse%20cx%3D%221110%22%20cy%3D%22626%22%20rx%3D%2292%22%20ry%3D%2228%22%20fill%3D%22%23FFA800%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%225%22%2F%3E%3Cellipse%20cx%3D%221110%22%20cy%3D%22592%22%20rx%3D%2292%22%20ry%3D%2228%22%20fill%3D%22%23FFA800%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%225%22%2F%3E%3Cellipse%20cx%3D%221110%22%20cy%3D%22558%22%20rx%3D%2292%22%20ry%3D%2228%22%20fill%3D%22%23FFA800%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%225%22%2F%3E%3Cellipse%20cx%3D%221110%22%20cy%3D%22524%22%20rx%3D%2292%22%20ry%3D%2228%22%20fill%3D%22%23FFA800%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%225%22%2F%3E%20%3Ctext%20x%3D%221110%22%20y%3D%22535%22%20text-anchor%3D%22middle%22%20fill%3D%22%2308215A%22%20font-family%3D%22Arial%2C%20Helvetica%2C%20sans-serif%22%20font-size%3D%2240%22%20font-weight%3D%22700%22%3EF%3C%2Ftext%3E%20%3Cellipse%20cx%3D%221260%22%20cy%3D%22660%22%20rx%3D%2272%22%20ry%3D%2222%22%20fill%3D%22%23FFA800%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%225%22%20opacity%3D%22.9%22%2F%3E%3Cellipse%20cx%3D%221260%22%20cy%3D%22626%22%20rx%3D%2272%22%20ry%3D%2222%22%20fill%3D%22%23FFA800%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%225%22%20opacity%3D%22.9%22%2F%3E%3Cellipse%20cx%3D%221260%22%20cy%3D%22592%22%20rx%3D%2272%22%20ry%3D%2222%22%20fill%3D%22%23FFA800%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%225%22%20opacity%3D%22.9%22%2F%3E%20%3Crect%20x%3D%221370%22%20y%3D%22560%22%20width%3D%2248%22%20height%3D%22120%22%20rx%3D%228%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.9%22%2F%3E%3Crect%20x%3D%221440%22%20y%3D%22470%22%20width%3D%2248%22%20height%3D%22210%22%20rx%3D%228%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.9%22%2F%3E%3Crect%20x%3D%221510%22%20y%3D%22380%22%20width%3D%2248%22%20height%3D%22300%22%20rx%3D%228%22%20fill%3D%22%23ffffff%22%20opacity%3D%22.9%22%2F%3E%20%3Cpolyline%20points%3D%221330%2C520%201400%2C450%201460%2C470%201540%2C300%22%20fill%3D%22none%22%20stroke%3D%22%23FFA800%22%20stroke-width%3D%2212%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%20%3Cpath%20d%3D%22M1512%20292%20L1556%20280%20L1548%20326%20Z%22%20fill%3D%22%23FFA800%22%2F%3E%20%3C%2Fsvg%3E","modules":[{"id":"rv-m1","title":"Les sources de revenus","lecons":[{"id":"rv-m1-l1","title":"D’où vient l’argent","type":"texte","duration":"7 min","description":"Objectif : connaître les quatre sources de revenus d’une vente solaire.","content":"Une installation solaire peut vous rapporter de quatre façons : la marge sur le matériel, la pose, la maintenance et, si vous êtes partenaire BestaSolar, les commissions. Aucune n’est garantie : tout dépend de vos prix, de vos frais et de votre travail.\n\nLe matériel : la Boutique affiche les prix publics. Votre marge, c’est l’écart entre votre prix d’achat réel et le prix payé par le client, moins le transport et vos frais.\n\nLa pose : c’est la ligne « Main d’œuvre » du devis. Au Togo, l’application la double automatiquement (sauf pour les kits haute tension).\n\n[[schema:marge]]\n\nLa maintenance : l’application la compte 30 000 F par an pour moins de 10 panneaux, puis 50 000 F plus 2 000 F par panneau au-delà de 10. Proposez le contrat dès la signature.\n\nLes commissions : quand la vente d’un de vos clients est validée, vous touchez 3 % du devis (niveau 1) et votre parrain 1,5 % (niveau 2). Suivez-les dans Plus → Mon espace partenaire.\n\nExemple — un Kit 5 kWh vendu 1 180 000 F à Cotonou : 75 000 F de pose, 35 400 F de commission (3 %), et 30 000 F par an si le client prend le contrat de maintenance.\n\nErreurs fréquentes sur le terrain :\n- Brader la pose pour signer : c’est souvent votre vraie marge.\n- Oublier le transport du matériel dans le calcul.\n- Promettre au client un prix du matériel que vous ne maîtrisez pas.","actionTitle":"L’essentiel","actionContent":"- Quatre sources : matériel, pose, maintenance, commissions.\n- Calculez toujours APRÈS vos frais (transport, outillage).\n- La maintenance rapporte chaque année, pas une seule fois."},{"id":"rv-m1-quiz","title":"Quiz — Les revenus","type":"quiz","duration":"3 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"rv-m1-quiz-q1","question":"Quelle commission touchez-vous quand la vente d’un de vos clients est validée ?","choix":["1,5 % du devis","3 % du devis","10 % du devis"],"bonne":1,"explication":"Niveau 1 : 3 % pour le technicien propriétaire du client ; niveau 2 : 1,5 % pour son parrain."},{"id":"rv-m1-quiz-q2","question":"Une installation de 6 panneaux : quelle maintenance annuelle l’application prévoit-elle ?","choix":["30 000 F par an","50 000 F par an","62 000 F par an"],"bonne":0,"explication":"Moins de 10 panneaux : 30 000 F par an."},{"id":"rv-m1-quiz-q3","question":"Au Togo, la ligne « Main d’œuvre » d’un kit basse tension est…","choix":["la même qu’au Bénin","doublée automatiquement","supprimée"],"bonne":1,"explication":"L’application double la main-d’œuvre pour un chantier togolais, sauf pour les kits haute tension."},{"id":"rv-m1-quiz-q4","question":"Votre vraie marge sur le matériel, c’est…","choix":["Le prix public","Le total du devis","L’écart entre votre prix d’achat et le prix client, moins vos frais"],"bonne":2,"explication":"Le prix public n’est pas un bénéfice : seul l’écart, frais déduits, l’est."}]}]},{"id":"rv-m2","title":"Trouver ses clients","lecons":[{"id":"rv-m2-l1","title":"Quartier, WhatsApp, bouche-à-oreille","type":"texte","duration":"5 min","description":"Objectif : remplir votre liste de pistes sans budget publicitaire.","content":"Vos premiers clients sont autour de vous : voisins, commerçants du marché, églises, mosquées, associations. Ceux que les coupures font perdre de l’argent — boutiques, salons, ateliers, maquis — sont les plus pressés.\n\nChaque contact intéressé devient une piste : Suivi clients → « Nouvelle piste ». Notez d’où il vient (« marché de Zongo », « recommandé par M. Bio ») : vous saurez ce qui marche.\n\nSur WhatsApp, publiez en statut une installation terminée (avec l’accord du client) et un chiffre parlant tiré du Simulateur ROI, comme le prix du kWh au groupe électrogène.\n\nAprès chaque installation réussie, demandez deux noms à votre client. Un client satisfait qui recommande, c’est la vente la plus facile.\n\nExemple — à Sokodé, Aïcha fait le tour des salons de coiffure du quartier avec le Simulateur ROI. En deux semaines, elle a ouvert onze pistes.\n\nErreurs fréquentes sur le terrain :\n- Noter les contacts dans un cahier au lieu de l’application : ils se perdent.\n- Publier la photo d’un client sans son accord.","actionTitle":"L’essentiel","actionContent":"- Visez d’abord ceux que les coupures font perdre de l’argent.\n- Chaque contact = une piste, avec sa source.\n- Après chaque pose : demandez deux noms."},{"id":"rv-m2-l2","title":"Votre lien de parrainage","type":"texte","duration":"5 min","description":"Objectif : faire travailler votre lien de parrainage pour vous.","content":"Dans Plus → Mon espace partenaire, vous trouvez votre code (NOM-XXXXXX) et vos liens : « Copier le lien » pour le site, et « Lien de l’app » pour l’application Android, avec votre code déjà rempli.\n\nPartagez-le dans vos statuts et vos groupes WhatsApp. Chaque ouverture est comptée dans « Clics sur mon lien » (une fois par personne et par 24 h), et chaque inscription dans « Inscriptions par mon lien ».\n\nLes personnes inscrites avec votre code deviennent vos filleuls (« Mes filleuls »). Quand leurs ventes sont validées, vous touchez le niveau 2 : 1,5 % du devis.\n\nVos commissions s’accumulent dans « À réclamer ». Dès 5 000 F, « Demander un paiement » envoie la demande au gérant, qui règle sur votre numéro Mobile Money.\n\nExemple — Koffi partage son lien dans le groupe WhatsApp des électriciens de Kpalimé. Trois collègues s’inscrivent avec son code et deviennent ses filleuls.\n\nErreurs fréquentes sur le terrain :\n- Changer de numéro Mobile Money sans le mettre à jour dans « Mon réseau et mon paiement ».\n- Partager une capture d’écran du code au lieu du lien : presque personne ne le recopie.","actionTitle":"L’essentiel","actionContent":"- Votre code lie le filleul pour de bon.\n- « Clics sur mon lien » dit si votre partage marche.\n- Paiement des commissions dès 5 000 F, sur demande."},{"id":"rv-m2-quiz","title":"Quiz — Trouver ses clients","type":"quiz","duration":"3 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"rv-m2-quiz-q1","question":"Quels clients viser en premier ?","choix":["Ceux que les coupures font perdre de l’argent (boutiques, salons, ateliers)","Ceux qui n’ont jamais de coupure","Uniquement les clients des concurrents"],"bonne":0,"explication":"Ceux qui perdent de l’argent à chaque coupure ont un besoin urgent : ils décident plus vite."},{"id":"rv-m2-quiz-q2","question":"Un nouveau contact est intéressé. Que faire dans l’application ?","choix":["Rien pour l’instant","L’ajouter dans la Boutique","Suivi clients → « Nouvelle piste », en notant d’où il vient"],"bonne":2,"explication":"La piste garde le contact, et la source vous dira plus tard quel canal fonctionne."},{"id":"rv-m2-quiz-q3","question":"Une personne inscrite avec votre code vend une installation validée. Que touchez-vous ?","choix":["Rien","1,5 % du devis (niveau 2)","50 %"],"bonne":1,"explication":"Le parrain touche le niveau 2 : 1,5 % des ventes validées de ses filleuls."},{"id":"rv-m2-quiz-q4","question":"À partir de quel montant pouvez-vous demander le paiement de vos commissions ?","choix":["500 F","5 000 F","100 000 F"],"bonne":1,"explication":"« Demander un paiement » s’ouvre dès 5 000 F à réclamer."}]}]},{"id":"rv-m3","title":"Piloter son activité avec le tableau de bord","lecons":[{"id":"rv-m3-l1","title":"Les bons chiffres à regarder","type":"texte","duration":"7 min","description":"Objectif : savoir où vous perdez vos ventes, grâce aux indicateurs.","content":"Une vente suit un entonnoir : beaucoup de contacts, moins de pistes sérieuses, encore moins de devis, et quelques ventes. Le tableau de bord mesure chaque étage.\n\n[[schema:entonnoir]]\n\nRegardez chaque semaine « Pistes actives », « Devis · ce mois » et « Gagnées · ce mois ». Dans « Indicateurs clés », le « Taux de conversion » et la « Transformation devis → commande » disent combien de devis deviennent des ventes.\n\nBeaucoup de pistes, peu de devis : vous ne visitez pas assez. Beaucoup de devis, peu de ventes : travaillez la présentation (fiche, Simulateur ROI) et les relances.\n\n« À relancer » et « Devis sans suite » sont vos listes de travail du jour. « Pistes par étape » montre où vos affaires s’entassent.\n\nExemple — ce mois-ci, Rachidi a 20 pistes actives, 8 devis et 1 vente. Son problème n’est pas la prospection mais les relances : il traite ses 5 « Devis sans suite » dans la semaine.\n\nErreurs fréquentes sur le terrain :\n- Ne regarder que le chiffre d’affaires.\n- Garder des pistes mortes : elles faussent le taux de conversion.","actionTitle":"L’essentiel","actionContent":"- Contacts → pistes → devis → ventes : trouvez l’étage qui fuit.\n- Peu de devis : plus de visites. Peu de ventes : meilleures relances.\n- Un coup d’œil par semaine, toujours au même moment."},{"id":"rv-m3-quiz","title":"Quiz — Les indicateurs","type":"quiz","duration":"3 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"rv-m3-quiz-q1","question":"Beaucoup de pistes, très peu de devis. Le problème est surtout…","choix":["La relance","Les visites et les dimensionnements","Le prix"],"bonne":1,"explication":"Les pistes ne se transforment pas en devis : il faut visiter et dimensionner davantage."},{"id":"rv-m3-quiz-q2","question":"Beaucoup de devis, très peu de ventes. Que travailler ?","choix":["La prospection","Rien","La présentation et les relances"],"bonne":2,"explication":"Les clients reçoivent des devis mais ne signent pas : la fiche, le Simulateur ROI et les relances font la différence."},{"id":"rv-m3-quiz-q3","question":"Quel indicateur dit combien de devis deviennent des ventes ?","choix":["Nouvelles · 7j","Transformation devis → commande","Catalogue par catégorie"],"bonne":1,"explication":"Il compare les devis acceptés aux devis émis."},{"id":"rv-m3-quiz-q4","question":"Pourquoi passer en « Perdu » une affaire morte ?","choix":["Pour garder des indicateurs justes","Pour la cacher au gérant","Ce n’est pas utile"],"bonne":0,"explication":"Une affaire morte laissée ouverte fausse vos pistes actives et votre taux de conversion."}]}]},{"id":"rv-m4","title":"Fidéliser","lecons":[{"id":"rv-m4-l1","title":"SAV, maintenance, recommandations","type":"texte","duration":"5 min","description":"Objectif : transformer un client installé en revenus réguliers et en recommandations.","content":"Le travail ne s’arrête pas à la pose. Dans la semaine qui suit, appelez le client : tout fonctionne ? A-t-il compris l’écran de l’onduleur ? Ce simple appel évite beaucoup de pannes « mystère ».\n\nProposez le contrat de maintenance annuel dès la signature : nettoyage des panneaux, serrage des connexions, contrôle de la batterie et des protections. La fiche de dimensionnement en affiche déjà le montant.\n\nGardez la fiche du client à jour dans l’application, avec la date de pose dans les notes : vous saurez quand revenir.\n\nUn client satisfait est votre meilleur vendeur. Demandez-lui deux noms, et donnez-lui votre lien de parrainage à transmettre.\n\nExemple — six mois après la pose, Serge repasse chez M. Akakpo à Aného pour nettoyer les panneaux couverts de poussière d’harmattan. Le voisin, qui regardait, lui demande un devis.\n\nErreurs fréquentes sur le terrain :\n- Disparaître après l’encaissement : le client raconte la panne à tout le quartier.\n- Laisser la poussière d’harmattan sur les panneaux : la production chute.","actionTitle":"L’essentiel","actionContent":"- Un appel la première semaine.\n- Le contrat de maintenance se propose à la signature.\n- Chaque visite de maintenance peut amener une nouvelle vente."},{"id":"rv-m4-quiz","title":"Quiz — Fidéliser","type":"quiz","duration":"3 min","description":"Cochez une réponse par question, puis vérifiez : chaque réponse est expliquée.","questions":[{"id":"rv-m4-quiz-q1","question":"Quand proposer le contrat de maintenance ?","choix":["Après la première panne","Jamais","Dès la signature"],"bonne":2,"explication":"À la signature, le client est en confiance et voit le montant sur la fiche de dimensionnement."},{"id":"rv-m4-quiz-q2","question":"Pourquoi appeler le client la semaine qui suit la pose ?","choix":["Ce n’est pas utile","Pour lui vendre un autre kit tout de suite","Pour vérifier que tout marche et qu’il sait utiliser son installation"],"bonne":2,"explication":"Un client qui comprend son installation l’utilise bien, et la recommande."},{"id":"rv-m4-quiz-q3","question":"En saison d’harmattan, que faire en priorité lors d’une visite ?","choix":["Nettoyer les panneaux","Changer la batterie","Rien"],"bonne":0,"explication":"La poussière sur les panneaux fait chuter la production : un nettoyage la rétablit."}]}]},{"id":"rv-m5","title":"Plan d’action sur 30 jours","lecons":[{"id":"rv-m5-l1","title":"Semaine par semaine","type":"texte","duration":"8 min","description":"Objectif : organiser vos 30 prochains jours pour viser vos 5 premiers clients.","content":"Cinq clients en 30 jours, c’est un objectif, pas une promesse : tout dépend de votre zone, de vos prix et du temps que vous y mettez. Le plan ci-dessous vous donne une méthode.\n\nSemaine 1 — Préparer :\n- Terminer les formations « Démarrer » et « Créer des devis qui signent ».\n- Connaître vos kits et leurs prix dans l’application.\n- Préparer votre lien de parrainage et un message WhatsApp de présentation.\n\nSemaine 2 — Prospecter :\n- Ouvrir 20 pistes dans Suivi clients (voisins, commerçants, ateliers).\n- Noter la source de chaque contact.\n- Faire le Simulateur ROI avec les plus pressés.\n\nSemaine 3 — Visiter et chiffrer :\n- Visiter au moins 8 clients.\n- Faire leur dimensionnement et leur devis le jour même.\n- Envoyer devis et fiche sur WhatsApp.\n\nSemaine 4 — Relancer et signer :\n- Traiter chaque « Devis sans suite ».\n- Passer les « non » en « Perdu ».\n- À chaque signature : contrat de maintenance et deux noms demandés.\n\nExemple — le premier mois, Adjoa a ouvert 20 pistes, fait 9 devis et signé 2 ventes. Le deuxième mois, ses premiers clients lui ont recommandé quatre voisins.\n\nErreurs fréquentes sur le terrain :\n- Prospecter sans jamais relancer.\n- Viser trop large : commencez par votre quartier.","actionTitle":"L’essentiel","actionContent":"- Une semaine, un objectif.\n- Tout passe par l’application : pistes, devis, relances.\n- Faites le point chaque vendredi avec le tableau de bord."},{"id":"rv-m5-l2","title":"La checklist des 30 jours (PDF)","type":"pdf","duration":"2 min","url":"/formations/checklist-30-jours.pdf","description":"Le plan des 30 jours en une page, à imprimer ou à garder sur votre téléphone. Cochez chaque action au fil des semaines.","actionTitle":"L’essentiel","actionContent":"- Une page, quatre semaines, une case par action.\n- Gardez-la à côté de votre tableau de bord."},{"id":"rv-final-quiz","title":"Quiz final — Gagner de l’argent avec BestaSolar Pro","type":"quiz","duration":"5 min","description":"Cinq questions sur toute la formation. Chaque réponse est expliquée.","questions":[{"id":"rv-final-quiz-q1","question":"Quelles sont les quatre sources de revenus d’une vente solaire ?","choix":["Matériel, pose, maintenance, commissions","Seulement le matériel","Publicité, transport, pose, matériel"],"bonne":0,"explication":"Le matériel, la pose, la maintenance chaque année et, pour un partenaire BestaSolar, les commissions."},{"id":"rv-final-quiz-q2","question":"Votre filleul vend une installation validée. Vous touchez…","choix":["3 %","1,5 %","rien"],"bonne":1,"explication":"Le parrain touche le niveau 2 : 1,5 % du devis."},{"id":"rv-final-quiz-q3","question":"Beaucoup de devis, peu de ventes. La priorité ?","choix":["Ouvrir plus de pistes","Baisser tous les prix","Mieux présenter et relancer"],"bonne":2,"explication":"Les devis existent : c’est la présentation et les relances qui les transforment."},{"id":"rv-final-quiz-q4","question":"Que proposer à la signature pour un revenu chaque année ?","choix":["Le contrat de maintenance","Un deuxième onduleur","Rien"],"bonne":0,"explication":"La maintenance rapporte chaque année et garde le lien avec le client."},{"id":"rv-final-quiz-q5","question":"Le plan de 30 jours garantit-il 5 clients ?","choix":["Oui, toujours","Non : c’est une méthode, le résultat dépend de votre zone et de votre travail"],"bonne":1,"explication":"Aucun résultat n’est garanti : le plan organise votre travail, il ne remplace pas le terrain."}]}]}]}
]$academie$::jsonb) as c
   where not exists (
     select 1 from public.tombstones t
      where t.org_id = v_org and t.id = c ->> 'id' and t.collection = 'formations'
   )
  on conflict (org_id, id) do nothing;
  get diagnostics v_ajoutes = row_count;

  raise notice 'Académie BestaSolar : % cours ajouté(s) à l''organisation %.', v_ajoutes, v_org;
end $$;

-- CONTRÔLE — trois lignes attendues, « visible » à oui.
select f.id,
       f.data ->> 'title'                                         as titre,
       jsonb_array_length(f.data -> 'modules')                    as modules,
       case when coalesce(f.data ->> 'masque', 'false') = 'true'
            then 'non (masqué)' else 'oui' end                    as visible,
       f.updated_at
  from public.formations f
  join public.orgs o on o.id = f.org_id and o.kind = 'interne'
 where f.id in ('academie-demarrer', 'academie-devis', 'academie-revenus')
 order by f.id;
